void PortPatchRomFunctionPointers(void)
{
    u32 i, patched = 0;

    /* PORT-FNID: the fields hold code IDs, and a ROM function's ID is the
     * value the ROM already stores, so for every resolved entry this is now
     * a check rather than a write.  What it still writes is the two fields
     * the ROM leaves NULL, which get a reporting stub as before. */
    for (i = 0; i < sizeof(sRomStructFns) / sizeof(sRomStructFns[0]); i++) {
        void *served = Res_ServedAddr(sRomStructFns[i].at);
        u32 id = (u32)(uintptr_t)sRomStructFns[i].fn;
        u32 *at = (u32 *)(uintptr_t)sRomStructFns[i].at;

        if (*at != id) {
            *at = id;
            patched++;
        }
        /* PORT-FORK: and into the copy the resource layer serves, when the
         * table holding the field was relocated (platform/res.c). */
        if (served != (void *)at && *(u32 *)served != id)
            *(u32 *)served = id;
    }
    if (patched != 2)
        PortLog("[katam-port] ROM struct function pointers: %u of %u fields "
                "differ from their code ID (2 expected: the NULL ones)\n",
                (unsigned)patched, (unsigned)i);
}

